CREATE TABLE IF NOT EXISTS public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', business_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', role text NOT NULL DEFAULT 'member' CHECK (role IN ('member', 'admin')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.bot_instances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL, phone_number text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'disconnected' CHECK (status IN ('connected', 'connecting', 'disconnected', 'paused')), commands_run integer NOT NULL DEFAULT 0 CHECK (commands_run >= 0), last_seen_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE, plan text NOT NULL CHECK (plan IN ('Starter', 'Pro', 'Business')), amount_tzs integer NOT NULL CHECK (amount_tzs > 0), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'expired', 'cancelled')), starts_at timestamptz, ends_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.contact_leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, business text NOT NULL, phone text NOT NULL, email text NOT NULL DEFAULT '', plan text NOT NULL DEFAULT 'Pro' CHECK (plan IN ('Starter', 'Pro', 'Business')), message text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS bot_instances_user_id_idx ON public.bot_instances(user_id);
CREATE INDEX IF NOT EXISTS subscriptions_user_id_idx ON public.subscriptions(user_id);
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.bot_instances ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.contact_leads ENABLE ROW LEVEL SECURITY;
GRANT UPDATE (display_name, business_name, phone) ON public.profiles TO authenticated;
REVOKE INSERT, UPDATE, DELETE ON public.subscriptions FROM authenticated;
CREATE POLICY "profiles_select_own" ON public.profiles FOR SELECT TO authenticated USING (auth.uid() = id);
CREATE POLICY "profiles_insert_own" ON public.profiles FOR INSERT TO authenticated WITH CHECK (auth.uid() = id);
CREATE POLICY "profiles_update_own" ON public.profiles FOR UPDATE TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
CREATE POLICY "profiles_delete_own" ON public.profiles FOR DELETE TO authenticated USING (auth.uid() = id);
CREATE POLICY "bots_select_own" ON public.bot_instances FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY "bots_insert_own" ON public.bot_instances FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE POLICY "bots_update_own" ON public.bot_instances FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE POLICY "bots_delete_own" ON public.bot_instances FOR DELETE TO authenticated USING (auth.uid() = user_id);
CREATE POLICY "subscriptions_select_own" ON public.subscriptions FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY "subscriptions_insert_denied" ON public.subscriptions FOR INSERT TO authenticated WITH CHECK (false);
CREATE POLICY "subscriptions_update_denied" ON public.subscriptions FOR UPDATE TO authenticated USING (false) WITH CHECK (false);
CREATE POLICY "subscriptions_delete_denied" ON public.subscriptions FOR DELETE TO authenticated USING (false);
CREATE POLICY "leads_select_denied" ON public.contact_leads FOR SELECT TO anon, authenticated USING (false);
CREATE POLICY "leads_insert_public" ON public.contact_leads FOR INSERT TO anon, authenticated WITH CHECK (char_length(name) BETWEEN 2 AND 120 AND char_length(business) BETWEEN 2 AND 160 AND char_length(phone) BETWEEN 7 AND 30 AND char_length(message) <= 2000);
CREATE POLICY "leads_update_denied" ON public.contact_leads FOR UPDATE TO anon, authenticated USING (false) WITH CHECK (false);
CREATE POLICY "leads_delete_denied" ON public.contact_leads FOR DELETE TO anon, authenticated USING (false);
CREATE OR REPLACE FUNCTION public.handle_new_xmd_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles (id, display_name, business_name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data ->> 'display_name', ''), COALESCE(NEW.raw_user_meta_data ->> 'business_name', '')) ON CONFLICT (id) DO NOTHING; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS on_auth_user_created_xmd ON auth.users;
CREATE TRIGGER on_auth_user_created_xmd AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_xmd_user();
REVOKE EXECUTE ON FUNCTION public.handle_new_xmd_user() FROM PUBLIC, anon, authenticated;
